// Setloom. Generated by publish.py in the study folder: icons, mode switch, page.

// Setloom icons. Generated by icons.py: edit there.
// Each icon plays once as it enters the view, and again when the link, button
// or [data-icon-host] it labels is hovered or focused, unless it sits inside
// [data-icon-manual], where the page plays it with window.playIcon. Nothing plays under
// reduced motion, and without this script every icon simply rests, drawn.
(() => {
  "use strict";
  if (matchMedia("(prefers-reduced-motion: reduce)").matches) return;

  const running = (svg) => svg.getAnimations({ subtree: true }).some((a) => a.playState === "running");
  const play = (svg) => {
    if (running(svg)) return;
    for (const a of svg.getAnimations({ subtree: true })) { a.currentTime = 0; a.play(); }
  };
  window.playIcon = play;

  const seen = new IntersectionObserver((entries) => {
    for (const e of entries) if (e.isIntersecting) { play(e.target); seen.unobserve(e.target); }
  }, { threshold: 0.5 });

  for (const svg of document.querySelectorAll("svg.ic")) {
    svg.classList.add("armed");
    // Inside [data-icon-manual] the page decides when an icon plays.
    // There it rests drawn until played.
    if (svg.closest("[data-icon-manual]")) for (const a of svg.getAnimations({ subtree: true })) a.finish();
    else seen.observe(svg);
    const host = svg.closest("a, button, [data-icon-host]");
    host?.addEventListener("pointerenter", () => play(svg));
    host?.addEventListener("focusin", () => play(svg));
  }
})();

// Setloom stage studies: the mode switch. The page follows the system setting
// until the visitor chooses; the choice is stored and applied before first paint.
(() => {
  "use strict";
  const root = document.documentElement;
  const system = matchMedia("(prefers-color-scheme: dark)");
  const current = () => root.dataset.theme || (system.matches ? "dark" : "light");

  for (const button of document.querySelectorAll(".mode-switch")) {
    const label = () => button.setAttribute("aria-label", `Switch to ${current() === "dark" ? "light" : "dark"} mode`);
    button.addEventListener("click", () => {
      const next = current() === "dark" ? "light" : "dark";
      root.dataset.theme = next;
      try { localStorage.setItem("setloom-theme", next); } catch {}
      label();
      window.playIcon?.(button.querySelector("svg"));
    });
    system.addEventListener("change", label);
    label();
  }
})();

// Setloom, the page: the parts of the transport CSS cannot do alone.
// - Speed: scroll speed (or a pointer sweeping a staff) plucks the strings and
//   sets the tempo; both ring down by time. Rise is fast and fall slow, so it
//   reads as momentum rather than twitch.
// - Direction: play going down, rewind going up, hold when still.
// - The loop: lights down while the ring is on stage; each step plays its icons.
// - Copy: the quick-start commands, without prompts or comments.
(() => {
  "use strict";
  const reduced = matchMedia("(prefers-reduced-motion: reduce)").matches;
  const mast = document.querySelector(".mast");
  const strung = [document.querySelector(".hero"), document.querySelector(".foot")];

  // ---------- speed, tempo, direction ----------
  let amp = 0, tempo = 0, lastY = scrollY, lastT = performance.now(), awake = false, idle = 0;
  const tick = (now) => {
    const dt = Math.max(16, now - lastT);
    const dy = scrollY - lastY;
    const speed = Math.abs(dy) / dt * 1000;
    lastY = scrollY; lastT = now;
    const decay = Math.pow(0.955, dt / 16.7);
    amp = Math.max(Math.min(1, speed / 2600), amp * decay);
    const target = speed / 12;
    tempo += (target - tempo) * (target > tempo ? 0.34 : 0.055);
    if (Math.abs(dy) > 0.5) { mast.dataset.dir = dy > 0 ? "down" : "up"; idle = now; }
    else if (now - idle > 700) mast.dataset.dir = "hold";
    mast.style.setProperty("--bpm", Math.round(Math.min(tempo, 999)));
    if (!reduced) for (const el of strung) el?.style.setProperty("--amp", amp.toFixed(4));
    if (amp > 0.002 || mast.dataset.dir !== "hold") requestAnimationFrame(tick);
    else { awake = false; amp = 0; tempo = 0; for (const el of strung) el?.style.setProperty("--amp", "0"); }
  };
  const wake = () => { if (!awake) { awake = true; lastT = performance.now(); idle = lastT; requestAnimationFrame(tick); } };
  mast.dataset.dir = "hold";
  addEventListener("scroll", wake, { passive: true });

  if (!reduced) {
    for (const zone of [document.querySelector(".hero .stage"), document.querySelector(".coda")]) {
      let p = null;
      zone?.addEventListener("pointermove", (e) => {
        if (p) amp = Math.max(amp, Math.min(0.7, Math.hypot(e.clientX - p.x, e.clientY - p.y) / Math.max(8, e.timeStamp - p.t) / 4));
        p = { x: e.clientX, y: e.clientY, t: e.timeStamp };
        wake();
      });
    }
    // The draft is tuned by 1100 + 6 × 110 + 450 ms; then the strings sound once.
    setTimeout(() => { amp = Math.max(amp, 0.75); wake(); }, 2210);
  }

  // ---------- the loop: lights down, and each step plays ----------
  const root = document.documentElement;
  const runway = document.querySelector(".runway");
  new IntersectionObserver(([e]) => root.classList.toggle("lights", e.isIntersecting),
    { rootMargin: "-45% 0px -45% 0px" }).observe(runway);

  const pin = document.querySelector(".pin");
  const panels = document.querySelectorAll(".panel");
  const nodes = document.querySelectorAll(".node");
  let step = -1, queued = false;
  const check = () => {
    queued = false;
    const now = parseInt(getComputedStyle(pin).getPropertyValue("--step"), 10);
    if (now === step || Number.isNaN(now)) return;
    step = now;
    window.playIcon?.(panels[step]?.querySelector("svg.ic"));
    window.playIcon?.(nodes[step]?.querySelector("svg.ic"));
  };
  addEventListener("scroll", () => { if (!queued) { queued = true; requestAnimationFrame(check); } }, { passive: true });

  // ---------- copy ----------
  const button = document.getElementById("copy");
  const block = document.getElementById("quickstart");
  const status = document.getElementById("copy-status");
  button?.addEventListener("click", async () => {
    const commands = block.innerText.split("\n").filter((l) => l.startsWith("$ ")).map((l) => l.slice(2)).join("\n");
    const label = button.querySelector("span");
    try {
      await navigator.clipboard.writeText(commands);
      button.classList.add("done");
      label.textContent = "Copied";
      window.playIcon?.(button.querySelector(".i-check"));
      status.textContent = "Commands copied to the clipboard.";
    } catch {
      const range = document.createRange();
      range.selectNodeContents(block);
      getSelection()?.removeAllRanges();
      getSelection()?.addRange(range);
      status.textContent = "Commands selected. Copy them with the keyboard.";
    }
    setTimeout(() => { button.classList.remove("done"); label.textContent = "Copy commands"; status.textContent = ""; }, 2400);
  });
})();
